<?php
if (!defined('ABSPATH')) exit;
final class Zica_Posts_Admin {
 private $auth;private $discovery;private $outbox;
 public function __construct($auth,$discovery,$outbox){$this->auth=$auth;$this->discovery=$discovery;$this->outbox=$outbox;add_action('admin_menu',array($this,'menu'));add_action('admin_init',array($this,'settings'));add_action('admin_enqueue_scripts',array($this,'assets'));}
 public function menu(){add_menu_page('Zica Posts','Zica Posts','manage_options','zica-posts',array($this,'page'),'dashicons-networking',58);}
 public function settings(){register_setting('zica_posts_settings','zica_posts_cards_position',array('sanitize_callback'=>'sanitize_key'));register_setting('zica_posts_settings','zica_posts_cards_count',array('sanitize_callback'=>'absint'));register_setting('zica_posts_settings','zica_posts_ai_crawlers_enabled',array('sanitize_callback'=>'sanitize_text_field'));register_setting('zica_posts_settings','zica_posts_physical_files_enabled',array('sanitize_callback'=>'sanitize_text_field'));register_setting('zica_posts_settings','zica_posts_hub_enabled',array('sanitize_callback'=>'sanitize_text_field'));register_setting('zica_posts_settings','zica_posts_hub_webhook_url',array('sanitize_callback'=>array($this,'sanitize_hub_url')));register_setting('zica_posts_settings','zica_posts_hub_delegates_indexing',array('sanitize_callback'=>'sanitize_text_field'));register_setting('zica_posts_settings','zica_posts_hub_delegates_discovery',array('sanitize_callback'=>'sanitize_text_field'));}
 public function sanitize_hub_url($value){$url=esc_url_raw((string)$value);return $url&&$this->auth->hub_url_is_safe($url)?$url:'';}
 public function assets($hook){if('toplevel_page_zica-posts'!==$hook)return;wp_enqueue_style('zica-posts-admin',ZICA_POSTS_URL.'assets/admin.css',array(),ZICA_POSTS_VERSION);}
 public function page(){if(!current_user_can('manage_options'))return;$api=(string)get_option('zica_posts_api_key','');$secret=(string)get_option('zica_posts_hub_secret','');$counts=$this->outbox->counts();$root_writable=is_writable(ABSPATH);$search_visible='1'===(string)get_option('blog_public','1');echo '<div class="wrap zica-posts-admin"><div class="zica-posts-hero"><div class="zica-neural-core"><span></span><i></i><b></b></div><div class="zica-posts-kicker">ZICA.AI · NEURAL DISTRIBUTION LAYER</div><h1>Zica Posts '.esc_html(ZICA_POSTS_VERSION).'</h1><p>WordPress é o agente leve. Outbox, HMAC, idempotência, anti-eco e delegação de IndexNow conectam o site ao Zica Orchestrator sem transformar o PHP em worker de IA.</p><div class="zica-energy-line"></div></div><div class="zica-posts-grid"><section class="zica-posts-panel"><h2>Conexão segura</h2><p><strong>API Key:</strong> <code>'.esc_html($api).'</code></p><p><strong>Hub Secret:</strong> <code>'.esc_html(substr($secret,0,8).'••••••••'.substr($secret,-6)).'</code></p><p><strong>Namespace:</strong> <code>/wp-json/zica-posts/v1/</code></p></section><section class="zica-posts-panel"><h2>Outbox e infraestrutura</h2><p>Pending: '.esc_html(isset($counts['pending'])?$counts['pending']:0).' · Retry: '.esc_html(isset($counts['retry'])?$counts['retry']:0).' · Failed: '.esc_html(isset($counts['failed'])?$counts['failed']:0).'</p><p>Busca pública: <strong>'.($search_visible?'OK':'ATENÇÃO').'</strong> · Raiz gravável: <strong>'.($root_writable?'SIM':'fallback virtual').'</strong></p><p>Reconciliação fallback: 15:00 America/Sao_Paulo</p></section></div><form method="post" action="options.php" class="zica-posts-panel zica-posts-settings">';settings_fields('zica_posts_settings');echo '<h2>Controles</h2><label>Cards <select name="zica_posts_cards_position">';foreach(array('before_content'=>'Antes do conteúdo','after_p2'=>'Após 2º parágrafo','after_p4'=>'Após 4º parágrafo','after_content'=>'Após conteúdo','disabled'=>'Desativado') as $k=>$v)echo '<option value="'.esc_attr($k).'" '.selected(get_option('zica_posts_cards_position','after_content'),$k,false).'>'.esc_html($v).'</option>';echo '</select></label><label>Quantidade <input type="number" min="1" max="6" name="zica_posts_cards_count" value="'.esc_attr((int)get_option('zica_posts_cards_count',3)).'"></label><label><input type="checkbox" name="zica_posts_ai_crawlers_enabled" value="1" '.checked(get_option('zica_posts_ai_crawlers_enabled','1'),'1',false).'> Regras explícitas para crawlers conhecidos</label><label><input type="checkbox" name="zica_posts_physical_files_enabled" value="1" '.checked(get_option('zica_posts_physical_files_enabled','1'),'1',false).'> Gravar discovery files fisicamente quando permitido</label><label><input type="checkbox" name="zica_posts_hub_enabled" value="1" '.checked(get_option('zica_posts_hub_enabled','0'),'1',false).'> Enviar outbox ao Zica Orchestrator</label><label>Webhook Hub <input type="url" class="regular-text" name="zica_posts_hub_webhook_url" value="'.esc_attr(get_option('zica_posts_hub_webhook_url','')).'" placeholder="https://hub.exemplo.com/webhooks/wordpress"></label><label><input type="checkbox" name="zica_posts_hub_delegates_indexing" value="1" '.checked(get_option('zica_posts_hub_delegates_indexing','1'),'1',false).'> Hub é responsável pelo IndexNow (evita envio duplicado)</label><label><input type="checkbox" name="zica_posts_hub_delegates_discovery" value="1" '.checked(get_option('zica_posts_hub_delegates_discovery','0'),'1',false).'> Hub é responsável por arquivos discovery/edge</label>';submit_button('Salvar controles');echo '</form></div>';}
}
